[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Orchard — The Best Way to Buy the Products You Love</title>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary: #1d1d1f;
      --bg: #f5f5f7;
      --bg-white: #ffffff;
      --secondary: #6e6e73;
      --accent: #0066cc;
      --accent-hover: #0077ed;
      --border: #d2d2d7;
      --ribbon-bg: #1d1d1f;
      --ribbon-text: #f5f5f7;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: -apple-system, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
      background: var(--bg-white);
      color: var(--primary);
      -webkit-font-smoothing: antialiased;
    }

    a { text-decoration: none; color: inherit; }

    /* ── RIBBON ─────────────────────────────────────── */
    .ribbon {
      background: var(--ribbon-bg);
      color: var(--ribbon-text);
      text-align: center;
      padding: 10px 20px;
      font-size: 12px;
      line-height: 1.4;
    }
    .ribbon a { color: #2997ff; margin-left: 4px; }
    .ribbon a:hover { text-decoration: underline; }

    /* ── NAV ─────────────────────────────────────────── */
    nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
    }
    .nav-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 22px;
      height: 52px;
    }
    .nav-logo {
      font-size: 20px;
      font-weight: 700;
      letter-spacing: -0.5px;
      color: var(--primary);
    }
    .nav-links {
      display: flex;
      gap: 28px;
      list-style: none;
    }
    .nav-links a {
      font-size: 13px;
      color: var(--primary);
      opacity: 0.85;
      transition: opacity 0.2s;
    }
    .nav-links a:hover { opacity: 1; }
    .nav-links a.active { font-weight: 600; opacity: 1; }
    .nav-actions {
      display: flex;
      gap: 20px;
      align-items: center;
    }
    .nav-actions a {
      font-size: 13px;
      color: var(--accent);
    }
    .nav-actions a:hover { text-decoration: underline; }
    .nav-mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 4px; }

    /* ── HERO PRODUCT SHOWCASE ───────────────────────── */
    .showcase {
      background: var(--bg);
      padding: 40px 20px;
    }
    .showcase-grid {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
    }

    .tile {
      border-radius: 20px;
      overflow: hidden;
      position: relative;
      min-height: 340px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 32px;
      text-align: center;
      align-items: center;
      transition: transform 0.3s ease;
    }
    .tile:hover { transform: scale(1.01); }

    .tile-phone      { background: linear-gradient(160deg, #1c1c1e 0%, #2c2c2e 100%); color: #fff; }
    .tile-laptop-neo { background: linear-gradient(160deg, #e8eaf0 0%, #f0f2f7 100%); color: var(--primary); }
    .tile-tablet-pro { background: linear-gradient(160deg, #0a2240 0%, #1a3a6e 100%); color: #fff; }
    .tile-laptop-pro { background: linear-gradient(160deg, #1c1c1e 0%, #3a3a3c 100%); color: #fff; }
    .tile-earbuds    { background: linear-gradient(160deg, #f5e6d3 0%, #ede0cc 100%); color: var(--primary); }
    .tile-trade      { background: linear-gradient(160deg, #e3f0e8 0%, #d4e9db 100%); color: var(--primary); }

    .tile-product-img {
      width: 160px;
      height: 160px;
      margin: 0 auto 20px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .tile-product-img svg { width: 100%; height: 100%; }

    .tile-eyebrow {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      opacity: 0.6;
      margin-bottom: 6px;
    }
    .tile h2 {
      font-size: 28px;
      font-weight: 700;
      letter-spacing: -0.5px;
      line-height: 1.15;
      margin-bottom: 6px;
    }
    .tile p {
      font-size: 14px;
      opacity: 0.75;
      margin-bottom: 20px;
      max-width: 280px;
    }
    .tile-ctas {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }
    .btn-learn {
      font-size: 14px;
      font-weight: 500;
      color: var(--accent);
      border: none;
      background: none;
      cursor: pointer;
      padding: 0;
    }
    .btn-learn:hover { text-decoration: underline; }
    .btn-learn-light { color: #2997ff; }
    .btn-buy {
      font-size: 14px;
      font-weight: 500;
      background: var(--accent);
      color: #fff;
      border: none;
      border-radius: 980px;
      padding: 8px 20px;
      cursor: pointer;
      transition: background 0.2s;
    }
    .btn-buy:hover { background: var(--accent-hover); }
    .btn-buy-dark {
      background: rgba(255,255,255,0.2);
      color: #fff;
    }
    .btn-buy-dark:hover { background: rgba(255,255,255,0.3); }

    /* full-width tile spans both columns */
    .tile-full { grid-column: 1 / -1; min-height: 240px; flex-direction: row; text-align: left; justify-content: center; gap: 60px; }
    .tile-full .tile-product-img { margin: 0; flex-shrink: 0; }
    .tile-full .tile-content { display: flex; flex-direction: column; justify-content: center; }
    .tile-full .tile-ctas { justify-content: flex-start; }

    /* ── ENTERTAINMENT CAROUSEL ─────────────────────── */
    .entertain {
      background: var(--bg-white);
      padding: 60px 20px;
    }
    .section-header {
      max-width: 1200px;
      margin: 0 auto 32px;
    }
    .section-header h2 {
      font-size: 40px;
      font-weight: 700;
      letter-spacing: -1px;
      color: var(--primary);
      margin-bottom: 8px;
    }
    .section-header p {
      font-size: 17px;
      color: var(--secondary);
    }
    .tabs {
      max-width: 1200px;
      margin: 0 auto 28px;
      display: flex;
      gap: 0;
      border-bottom: 1px solid var(--border);
    }
    .tab-btn {
      background: none;
      border: none;
      cursor: pointer;
      font-size: 15px;
      font-weight: 500;
      color: var(--secondary);
      padding: 10px 24px 10px 0;
      position: relative;
      transition: color 0.2s;
    }
    .tab-btn::after {
      content: '';
      position: absolute;
      bottom: -1px;
      left: 0;
      right: 0;
      height: 2px;
      background: var(--primary);
      opacity: 0;
      transition: opacity 0.2s;
    }
    .tab-btn.active { color: var(--primary); }
    .tab-btn.active::after { opacity: 1; }
    .tab-btn:hover { color: var(--primary); }

    .tab-content { display: none; }
    .tab-content.active { display: block; }

    .entertain-cards {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 14px;
    }
    .entertain-card {
      border-radius: 16px;
      overflow: hidden;
      aspect-ratio: 3/4;
      position: relative;
      cursor: pointer;
      transition: transform 0.25s;
    }
    .entertain-card:hover { transform: scale(1.02); }
    .entertain-card-bg {
      width: 100%; height: 100%;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 20px;
    }
    .entertain-card-title {
      font-size: 16px;
      font-weight: 700;
      color: #fff;
      margin-bottom: 4px;
    }
    .entertain-card-sub {
      font-size: 13px;
      color: rgba(255,255,255,0.75);
      margin-bottom: 12px;
    }
    .entertain-cta {
      font-size: 13px;
      font-weight: 500;
      color: #fff;
      background: rgba(255,255,255,0.2);
      border: none;
      border-radius: 980px;
      padding: 7px 16px;
      cursor: pointer;
      display: inline-block;
      backdrop-filter: blur(10px);
      width: fit-content;
      transition: background 0.2s;
    }
    .entertain-cta:hover { background: rgba(255,255,255,0.3); }

    /* ── FOOTER ─────────────────────────────────────── */
    footer {
      background: var(--bg);
      border-top: 1px solid var(--border);
      padding: 40px 20px 20px;
    }
    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .footer-note {
      font-size: 12px;
      color: var(--secondary);
      border-bottom: 1px solid var(--border);
      padding-bottom: 20px;
      margin-bottom: 20px;
      line-height: 1.6;
    }
    .footer-cols {
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      gap: 20px;
      margin-bottom: 30px;
    }
    .footer-col h4 {
      font-size: 12px;
      font-weight: 600;
      color: var(--primary);
      margin-bottom: 12px;
    }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 8px; }
    .footer-col a {
      font-size: 12px;
      color: var(--secondary);
      transition: color 0.2s;
    }
    .footer-col a:hover { color: var(--primary); }
    .footer-bottom {
      border-top: 1px solid var(--border);
      padding-top: 16px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 10px;
    }
    .footer-bottom p { font-size: 12px; color: var(--secondary); }
    .footer-bottom-links {
      display: flex;
      gap: 20px;
      list-style: none;
      flex-wrap: wrap;
    }
    .footer-bottom-links a { font-size: 12px; color: var(--secondary); }
    .footer-bottom-links a:hover { color: var(--primary); }

    /* ── ACCORDION FOOTER on MOBILE ─────────────────── */
    .footer-col-toggle { display: none; }

    /* ── RESPONSIVE ──────────────────────────────────── */
    @media (max-width: 1024px) {
      .showcase-grid { grid-template-columns: 1fr; }
      .tile-full { flex-direction: column; text-align: center; gap: 20px; }
      .tile-full .tile-ctas { justify-content: center; }
      .entertain-cards { grid-template-columns: repeat(2, 1fr); }
      .footer-cols { grid-template-columns: repeat(4, 1fr); }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .nav-mobile-toggle { display: flex; align-items: center; }
      .nav-mobile-toggle svg { width: 20px; height: 20px; }
      .tile { min-height: 280px; padding: 24px 20px; }
      .tile h2 { font-size: 22px; }
      .section-header h2 { font-size: 28px; }
      .entertain-cards { grid-template-columns: repeat(2, 1fr); gap: 10px; }
      .footer-cols { grid-template-columns: 1fr; }
      .footer-col { border-bottom: 1px solid var(--border); }
      .footer-col-toggle { display: flex; justify-content: space-between; align-items: center; cursor: pointer; background: none; border: none; width: 100%; padding: 12px 0; }
      .footer-col-toggle h4 { font-size: 12px; font-weight: 600; color: var(--primary); margin: 0; }
      .footer-col ul { display: none; padding-bottom: 12px; }
      .footer-col.open ul { display: block; }
      .footer-col h4.desktop-heading { display: none; }
      .chevron { transition: transform 0.2s; display: inline-block; }
      .footer-col.open .chevron { transform: rotate(180deg); }
    }

    @media (max-width: 480px) {
      .showcase-grid { gap: 8px; }
      .tile-product-img { width: 120px; height: 120px; }
      .tabs { overflow-x: auto; padding-bottom: 2px; }
      .tab-btn { white-space: nowrap; }
      .entertain-cards { grid-template-columns: 1fr 1fr; }
    }

    /* Mobile nav overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(0,0,0,0.5);
      z-index: 200;
    }
    .mobile-nav.open { display: block; }
    .mobile-nav-panel {
      position: absolute;
      top: 0; right: 0;
      width: 280px; height: 100%;
      background: var(--bg-white);
      padding: 60px 30px 30px;
      overflow-y: auto;
    }
    .mobile-nav-close {
      position: absolute;
      top: 16px; right: 16px;
      background: none; border: none;
      font-size: 24px; cursor: pointer;
      color: var(--primary);
    }
    .mobile-nav-links { list-style: none; }
    .mobile-nav-links li { border-bottom: 1px solid var(--border); }
    .mobile-nav-links a {
      display: block;
      padding: 14px 0;
      font-size: 16px;
      color: var(--primary);
    }
  </style>
</head>
<body>

<!-- RIBBON -->
<div class="ribbon">
  Recycle an eligible device in a store and get 10% off an Orchard accessory.
  <a href="#">Find a store →</a>
</div>

<!-- NAV -->
<nav>
