        <svg viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M3 5h14v1.5H3V5zm0 4.5h14V11H3V9.5zm0 4.5h14v1.5H3V14z"/></svg>
      </button>
    </div>
  </div>
</nav>

<!-- MOBILE NAV -->
<div class="mobile-nav" id="mobileNav">
  <div class="mobile-nav-panel">
    <button class="mobile-nav-close" id="mobileNavClose">&times;</button>
    <ul class="mobile-nav-links">
      <li><a href="store.html">Store</a></li>
      <li><a href="shop-laptops.html">Laptops</a></li>
      <li><a href="shop-tablets.html">Tablets</a></li>
      <li><a href="#">Phone</a></li>
      <li><a href="#">Accessories</a></li>
      <li><a href="#">Support</a></li>
    </ul>
  </div>
</div>

<!-- PRODUCT SHOWCASE GRID -->
<section class="showcase">
  <div class="showcase-grid">

    <!-- Phone (full width) -->
    <div class="tile tile-phone tile-full">
      <div class="tile-product-img">
        <svg viewBox="0 0 160 160" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="45" y="10" width="70" height="140" rx="14" fill="#2c2c2e" stroke="#4a4a4c" stroke-width="1.5"/>
          <rect x="50" y="22" width="60" height="110" rx="8" fill="#1a1a1c"/>
          <rect x="65" y="14" width="30" height="5" rx="2.5" fill="#4a4a4c"/>
          <circle cx="80" cy="143" r="3" fill="#4a4a4c"/>
          <!-- screen glow -->
          <rect x="52" y="24" width="56" height="106" rx="7" fill="url(#phoneGrad)"/>
          <defs>
            <linearGradient id="phoneGrad" x1="52" y1="24" x2="108" y2="130" gradientUnits="userSpaceOnUse">
              <stop offset="0%" stop-color="#2997ff" stop-opacity="0.4"/>
              <stop offset="100%" stop-color="#5e5ce6" stop-opacity="0.2"/>
            </linearGradient>
          </defs>
        </svg>
      </div>
      <div class="tile-content">
        <p class="tile-eyebrow" style="color:rgba(255,255,255,0.5)">Latest Lineup</p>
        <h2>Phone</h2>
        <p>Meet the latest Phone lineup.</p>
        <div class="tile-ctas">
          <button class="btn-learn btn-learn-light">Learn more</button>
          <button class="btn-buy btn-buy-dark">Buy</button>
        </div>
      </div>
    </div>

    <!-- Laptop Neo -->
    <div class="tile tile-laptop-neo">
      <div class="tile-product-img">
        <svg viewBox="0 0 160 160" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="20" y="45" width="120" height="75" rx="8" fill="#c8cad0" stroke="#b0b2b8" stroke-width="1.5"/>
          <rect x="26" y="51" width="108" height="62" rx="5" fill="#1a1a1c"/>
          <rect x="28" y="53" width="104" height="58" rx="4" fill="#2a2a2c"/>
          <rect x="10" y="120" width="140" height="8" rx="4" fill="#c0c2c8"/>
          <rect x="55" y="122" width="50" height="4" rx="2" fill="#a0a2a8"/>
          <!-- screen content -->
          <rect x="35" y="60" width="90" height="4" rx="2" fill="#3a3a3c"/>
          <rect x="35" y="68" width="60" height="3" rx="1.5" fill="#2997ff" opacity="0.7"/>
          <rect x="35" y="75" width="80" height="3" rx="1.5" fill="#3a3a3c" opacity="0.5"/>
          <rect x="35" y="82" width="70" height="3" rx="1.5" fill="#3a3a3c" opacity="0.4"/>
        </svg>
      </div>
      <p class="tile-eyebrow">New</p>
      <h2>Laptop Neo</h2>
      <p>Amazing Laptop. Surprising price.</p>
      <div class="tile-ctas">
        <button class="btn-learn">Learn more</button>
        <button class="btn-buy">Buy</button>
      </div>
    </div>

    <!-- Tablet Pro -->
    <div class="tile tile-tablet-pro">
      <div class="tile-product-img">
        <svg viewBox="0 0 160 160" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="30" y="15" width="100" height="130" rx="12" fill="#1a3050" stroke="#2a4a7a" stroke-width="1.5"/>
          <rect x="36" y="22" width="88" height="116" rx="8" fill="#0a1a30"/>
          <rect x="38" y="24" width="84" height="112" rx="7" fill="url(#tabletGrad)"/>
          <circle cx="80" cy="148" r="0" fill="transparent"/>
          <rect x="68" y="17" width="24" height="4" rx="2" fill="#2a4a7a"/>
          <defs>
            <linearGradient id="tabletGrad" x1="38" y1="24" x2="122" y2="136" gradientUnits="userSpaceOnUse">
              <stop offset="0%" stop-color="#1a3a6e"/>
              <stop offset="100%" stop-color="#0a2040"/>
            </linearGradient>
          </defs>
          <!-- screen content lines -->
          <rect x="50" y="50" width="60" height="5" rx="2.5" fill="rgba(255,255,255,0.15)"/>
          <rect x="50" y="60" width="45" height="3" rx="1.5" fill="rgba(41,151,255,0.5)"/>
          <rect x="50" y="68" width="55" height="3" rx="1.5" fill="rgba(255,255,255,0.1)"/>
        </svg>
      </div>
      <p class="tile-eyebrow" style="color:rgba(255,255,255,0.5)">Pro</p>
      <h2>Tablet Pro</h2>
      <p>Advanced AI performance and game-changing capabilities.</p>
      <div class="tile-ctas">
        <button class="btn-learn btn-learn-light">Learn more</button>
        <button class="btn-buy btn-buy-dark">Buy</button>
      </div>
    </div>

    <!-- Laptop Pro -->
    <div class="tile tile-laptop-pro">
      <div class="tile-product-img">
        <svg viewBox="0 0 160 160" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="15" y="40" width="130" height="82" rx="9" fill="#2c2c2e" stroke="#3a3a3c" stroke-width="1.5"/>
          <rect x="21" y="46" width="118" height="69" rx="5" fill="#1a1a1c"/>
          <rect x="23" y="48" width="114" height="65" rx="4" fill="#111113"/>
          <rect x="5" y="122" width="150" height="9" rx="4.5" fill="#2a2a2c"/>
          <rect x="55" y="124" width="50" height="5" rx="2.5" fill="#222224"/>
          <rect x="30" y="57" width="100" height="5" rx="2.5" fill="#2a2a2c"/>
          <rect x="30" y="66" width="70" height="3" rx="1.5" fill="#2997ff" opacity="0.6"/>
          <rect x="30" y="73" width="85" height="3" rx="1.5" fill="#3a3a3c" opacity="0.5"/>
          <rect x="30" y="80" width="75" height="3" rx="1.5" fill="#3a3a3c" opacity="0.4"/>
          <rect x="30" y="87" width="90" height="3" rx="1.5" fill="#3a3a3c" opacity="0.3"/>
        </svg>
      </div>
      <p class="tile-eyebrow" style="color:rgba(255,255,255,0.5)">Pro</p>
      <h2>Laptop Pro</h2>
      <p>Now with O5, O5 Pro, and O5 Max.</p>
      <div class="tile-ctas">
        <button class="btn-learn btn-learn-light">Learn more</button>
        <button class="btn-buy btn-buy-dark">Buy</button>
      </div>
    </div>

    <!-- Earbuds Pro 3 -->
    <div class="tile tile-earbuds">
      <div class="tile-product-img">
        <svg viewBox="0 0 160 160" fill="none" xmlns="http://www.w3.org/2000/svg">
          <!-- Case -->
          <rect x="45" y="50" width="70" height="60" rx="20" fill="#d4c4a8" stroke="#c4b498" stroke-width="1.5"/>
          <line x1="80" y1="50" x2="80" y2="110" stroke="#c4b498" stroke-width="1"/>
          <!-- Left earbud -->
          <ellipse cx="62" cy="66" rx="10" ry="14" fill="#c8b890" stroke="#b8a880" stroke-width="1"/>
          <ellipse cx="62" cy="66" rx="5" ry="7" fill="#d8c8a0"/>
          <!-- Right earbud -->
          <ellipse cx="98" cy="66" rx="10" ry="14" fill="#c8b890" stroke="#b8a880" stroke-width="1"/>
          <ellipse cx="98" cy="66" rx="5" ry="7" fill="#d8c8a0"/>
          <!-- Lightning port -->
          <rect x="72" y="107" width="16" height="5" rx="2" fill="#b8a880"/>
        </svg>
