    .brand-badge { background:rgba(255,255,255,0.12); border:1px solid rgba(255,255,255,0.2); border-radius:980px; padding:10px 22px; font-size:14px; font-weight:500; color:#fff; cursor:pointer; backdrop-filter:blur(10px); transition:background 0.2s; }
    .brand-badge:hover { background:rgba(255,255,255,0.22); }

    /* ── SAVINGS CARDS ── */
    .savings-card {
      flex:0 0 220px;
      background:var(--bg);
      border-radius:16px;
      padding:24px 20px;
      display:flex;
      flex-direction:column;
      transition:transform 0.25s;
    }
    .section-alt .savings-card { background:#fff; }
    .savings-card:hover { transform:translateY(-4px); }
    .savings-card h3 { font-size:15px; font-weight:600; margin-bottom:8px; }
    .savings-card p { font-size:13px; color:var(--secondary); line-height:1.5; flex:1; }
    .savings-card a { display:inline-block; margin-top:14px; font-size:13px; font-weight:500; color:var(--accent); }
    .savings-card a:hover { text-decoration:underline; }

    /* ── QUICK LINKS ── */
    .quick-links { background:var(--bg-white); padding:40px 22px; border-top:1px solid var(--border); border-bottom:1px solid var(--border); }
    .quick-links-inner { max-width:1200px; margin:0 auto; display:flex; gap:12px; flex-wrap:wrap; justify-content:center; }
    .quick-link-btn { background:var(--bg); border:1.5px solid var(--border); border-radius:980px; padding:12px 24px; font-size:14px; font-weight:500; color:var(--primary); cursor:pointer; transition:all 0.2s; white-space:nowrap; }
    .quick-link-btn:hover { background:var(--primary); color:#fff; border-color:var(--primary); }

    /* ── FOOTER ── */
    footer { background:var(--bg); border-top:1px solid var(--border); padding:40px 20px 20px; }
    .footer-inner { max-width:1200px; margin:0 auto; }
    .footer-note { font-size:12px; color:var(--secondary); border-bottom:1px solid var(--border); padding-bottom:20px; margin-bottom:20px; line-height:1.6; }
    .footer-cols { display:grid; grid-template-columns:repeat(7,1fr); gap:20px; margin-bottom:30px; }
    .footer-col h4 { font-size:12px; font-weight:600; color:var(--primary); margin-bottom:12px; }
    .footer-col ul { list-style:none; }
    .footer-col li { margin-bottom:8px; }
    .footer-col a { font-size:12px; color:var(--secondary); transition:color 0.2s; }
    .footer-col a:hover { color:var(--primary); }
    .footer-bottom { border-top:1px solid var(--border); padding-top:16px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; }
    .footer-bottom p { font-size:12px; color:var(--secondary); }
    .footer-bottom-links { display:flex; gap:20px; list-style:none; flex-wrap:wrap; }
    .footer-bottom-links a { font-size:12px; color:var(--secondary); }
    .footer-bottom-links a:hover { color:var(--primary); }
    .footer-col-toggle { display:none; }

    /* ── RESPONSIVE ── */
    @media (max-width:1024px) {
      .footer-cols { grid-template-columns:repeat(4,1fr); }
      .carousel-arrow.prev { left:-10px; }
      .carousel-arrow.next { right:-10px; }
    }
    @media (max-width:768px) {
      .nav-links { display:none; }
      .nav-mobile-toggle { display:flex; align-items:center; }
      .nav-mobile-toggle svg { width:20px; height:20px; }
      .store-hero h1 { font-size:36px; }
      .store-hero p { font-size:16px; }
      .section-header h2 { font-size:26px; }
      .footer-cols { grid-template-columns:1fr; }
      .footer-col { border-bottom:1px solid var(--border); }
      .footer-col-toggle { display:flex; justify-content:space-between; align-items:center; cursor:pointer; background:none; border:none; width:100%; padding:12px 0; }
      .footer-col-toggle h4 { font-size:12px; font-weight:600; color:var(--primary); margin:0; }
      .footer-col ul { display:none; padding-bottom:12px; }
      .footer-col.open ul { display:block; }
      .footer-col h4.desktop-heading { display:none; }
      .chevron { transition:transform 0.2s; }
      .footer-col.open .chevron { transform:rotate(180deg); }
      .icon-bar-item { padding:12px 14px; }
      .icon-bar-item span { font-size:10px; }
      .brand-collab h2 { font-size:28px; }
    }

    /* Mobile nav */
    .mobile-nav { display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.5); z-index:200; }
    .mobile-nav.open { display:block; }
