<script>
  // ── Carousel logic ────────────────────────────────────────
  function initCarousel(wrapId) {
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;
    const track = wrap.querySelector('.carousel-track');
    const container = wrap.querySelector('.carousel-container');
    const prevBtn = wrap.querySelector('.carousel-arrow.prev');
    const nextBtn = wrap.querySelector('.carousel-arrow.next');
    if (!track || !prevBtn || !nextBtn) return;

    let currentIndex = 0;

    function getCardWidth() {
      const card = track.children[0];
      if (!card) return 240;
      const gap = 16;
      return card.offsetWidth + gap;
    }

    function getVisibleCount() {
      return Math.floor(container.offsetWidth / getCardWidth()) || 1;
    }

    function getMaxIndex() {
      const total = track.children.length;
      const visible = getVisibleCount();
      return Math.max(0, total - visible);
    }

    function update() {
      const cw = getCardWidth();
      track.style.transform = `translateX(-${currentIndex * cw}px)`;
      prevBtn.classList.toggle('hidden', currentIndex === 0);
      nextBtn.classList.toggle('hidden', currentIndex >= getMaxIndex());
    }

    prevBtn.addEventListener('click', () => {
      currentIndex = Math.max(0, currentIndex - 1);
      update();
    });
    nextBtn.addEventListener('click', () => {
      currentIndex = Math.min(getMaxIndex(), currentIndex + 1);
      update();
    });

    window.addEventListener('resize', () => {
      currentIndex = Math.min(currentIndex, getMaxIndex());
      update();
    });

    update();
  }

  ['latestCarousel','helpCarousel','differenceCarousel','accessoriesCarousel','audioCarousel','savingsCarousel']
    .forEach(initCarousel);

  // Mobile nav
  const mobileMenuToggle = document.getElementById('mobileMenuToggle');
  const mobileNav = document.getElementById('mobileNav');
  const mobileNavClose = document.getElementById('mobileNavClose');
  mobileMenuToggle.addEventListener('click', () => mobileNav.classList.add('open'));
  mobileNavClose.addEventListener('click', () => mobileNav.classList.remove('open'));
  mobileNav.addEventListener('click', e => { if(e.target === mobileNav) mobileNav.classList.remove('open'); });

  // Footer accordion
  document.querySelectorAll('.footer-col-toggle').forEach(btn => {
    btn.addEventListener('click', () => btn.closest('.footer-col').classList.toggle('open'));
  });
</script>
