<script>
  // ── Carousel ───────────────────────────────────────
  function initCarousel(wrapId) {
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;
    const track = wrap.querySelector('.carousel-track');
    const container = wrap.querySelector('.carousel-container');
    const prevBtn = wrap.querySelector('.carousel-arrow.prev');
    const nextBtn = wrap.querySelector('.carousel-arrow.next');
    if (!track || !prevBtn || !nextBtn) return;
    let currentIndex = 0;
    function getCardWidth() { const card = track.children[0]; return card ? card.offsetWidth + 16 : 240; }
    function getVisibleCount() { return Math.floor(container.offsetWidth / getCardWidth()) || 1; }
    function getMaxIndex() { return Math.max(0, track.children.length - getVisibleCount()); }
    function update() {
      track.style.transform = `translateX(-${currentIndex * getCardWidth()}px)`;
      prevBtn.classList.toggle('hidden', currentIndex === 0);
      nextBtn.classList.toggle('hidden', currentIndex >= getMaxIndex());
    }
    prevBtn.addEventListener('click', () => { currentIndex = Math.max(0, currentIndex - 1); update(); });
    nextBtn.addEventListener('click', () => { currentIndex = Math.min(getMaxIndex(), currentIndex + 1); update(); });
    window.addEventListener('resize', () => { currentIndex = Math.min(currentIndex, getMaxIndex()); update(); });
    update();
  }
  initCarousel('modelsCarousel');
  initCarousel('accessoriesCarousel');

  // ── Section Nav ────────────────────────────────────
  const sectionNavBtns = document.querySelectorAll('.section-nav-btn');
  sectionNavBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const target = document.getElementById(btn.dataset.target);
      if (target) target.scrollIntoView({ behavior: 'smooth' });
      sectionNavBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
  });

  // Update active state on scroll
  const sections = Array.from(sectionNavBtns).map(btn => document.getElementById(btn.dataset.target)).filter(Boolean);
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const id = entry.target.id;
        sectionNavBtns.forEach(btn => {
          btn.classList.toggle('active', btn.dataset.target === id);
        });
      }
    });
  }, { rootMargin: '-110px 0px -60% 0px', threshold: 0 });
  sections.forEach(s => s && observer.observe(s));

  // Mobile nav
  const mobileMenuToggle = document.getElementById('mobileMenuToggle');
  const mobileNav = document.getElementById('mobileNav');
  const mobileNavClose = document.getElementById('mobileNavClose');
  mobileMenuToggle.addEventListener('click', () => mobileNav.classList.add('open'));
  mobileNavClose.addEventListener('click', () => mobileNav.classList.remove('open'));
  mobileNav.addEventListener('click', e => { if(e.target === mobileNav) mobileNav.classList.remove('open'); });

  // Footer accordion
  document.querySelectorAll('.footer-col-toggle').forEach(btn => {
    btn.addEventListener('click', () => btn.closest('.footer-col').classList.toggle('open'));
  });
